#!/usr/bin/env node
/**
 * R88 agent plan P09 Supabase-first step: apply migration 0041
 * (media evidence + access) to the Supabase canonical database BEFORE the
 * worker push. Additive only: 3 columns on horse_media (consent_state with
 * the honest visibility backfill, quarantine_reason, quarantined_at), one
 * new table (media_access_grants) and 2 indexes.
 *
 * The Postgres translation is generated by the production converter
 * (scripts/check-migration-translation.mjs passes); inline UNIQUEs and
 * Postgres forms are hand-verified here per the R81 discipline.
 *
 * Usage:
 *   SUPABASE_DATABASE_URL=... node scripts/apply-0041-to-supabase.mjs
 */
import { requireCanonicalMigrationApproval } from "./lib/migration-approval.mjs";

const url = process.env.SUPABASE_DATABASE_URL;
if (!url) {
  console.error("Need SUPABASE_DATABASE_URL");
  process.exit(2);
}
requireCanonicalMigrationApproval(url, "0041");
const { default: postgres } = await import("postgres");
const sql = postgres(url, { max: 1, idle_timeout: 5, connect_timeout: 15 });

try {
  const existing = await sql`
    SELECT column_name FROM information_schema.columns
    WHERE table_schema='public' AND table_name='horse_media' AND column_name IN ('consent_state','quarantine_reason','quarantined_at')
  `;
  const have = new Set(existing.map((row) => row.column_name));

  if (!have.has("consent_state")) {
    await sql.unsafe(`ALTER TABLE horse_media ADD COLUMN consent_state TEXT NOT NULL DEFAULT 'private'
      CHECK (consent_state IN ('private','shared_public'))`);
    // Honest backfill: rows the legacy predicate ALREADY serves publicly get
    // the matching consent state — nothing becomes more visible than today.
    const backfilled = await sql.unsafe(`
      UPDATE horse_media
      SET consent_state = 'shared_public'
      WHERE media_type = 'photo'
        AND role IN ('profile','gallery')
        AND verification IN ('federation_verified','owner_submitted')
    `);
    console.log(`OK horse_media.consent_state added; backfilled ${backfilled.count} already-public rows to shared_public`);
  } else {
    console.log("SKIP horse_media.consent_state (already present)");
  }

  if (!have.has("quarantine_reason")) {
    await sql.unsafe(`ALTER TABLE horse_media ADD COLUMN quarantine_reason TEXT`);
    console.log("OK horse_media.quarantine_reason added");
  }
  if (!have.has("quarantined_at")) {
    await sql.unsafe(`ALTER TABLE horse_media ADD COLUMN quarantined_at TEXT`);
    console.log("OK horse_media.quarantined_at added");
  }

  await sql.unsafe(`
    CREATE TABLE IF NOT EXISTS media_access_grants (
      id BIGSERIAL PRIMARY KEY,
      media_id TEXT NOT NULL REFERENCES horse_media(id) ON DELETE CASCADE,
      granted_to_user_id TEXT NOT NULL,
      granted_by_user_id TEXT NOT NULL,
      expires_at TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      revoked_at TEXT
    )
  `);
  await sql.unsafe(`CREATE INDEX IF NOT EXISTS idx_media_access_grants_media ON media_access_grants(media_id, revoked_at)`);
  await sql.unsafe(`CREATE INDEX IF NOT EXISTS idx_media_access_grants_user ON media_access_grants(granted_to_user_id, expires_at)`);

  const verify = await sql`
    SELECT column_name, data_type FROM information_schema.columns
    WHERE table_schema='public' AND table_name='media_access_grants' ORDER BY ordinal_position
  `;
  console.log("OK media_access_grants:", verify.map((row) => row.column_name).join(", "));
  const counts = await sql`SELECT consent_state, COUNT(*)::int AS n FROM horse_media GROUP BY consent_state`;
  console.log("consent_state census:", JSON.stringify(counts));
  console.log("apply-0041: Supabase canonical updated (P09 evidence consent + short-lived access)");
} finally {
  await sql.end({ timeout: 5 });
}
